class Solution {
    public boolean isInterleave(String s1, String s2, String s3) {
        if (s1.length() + s2.length() != s3.length()) return false;
        return matches(s1, s2, s3, 0, 0);
    }

    private boolean matches(String first, String second, String target, int i, int j) {
        int k = i + j;
        if (k == target.length()) return true;
        boolean useFirst = i < first.length() && first.charAt(i) == target.charAt(k)
                && matches(first, second, target, i + 1, j);
        boolean useSecond = j < second.length() && second.charAt(j) == target.charAt(k)
                && matches(first, second, target, i, j + 1);
        return useFirst || useSecond;
    }
}

