class Solution {
    public boolean isInterleave(String s1, String s2, String s3) {
        int firstLength = s1.length();
        int secondLength = s2.length();
        if (firstLength + secondLength != s3.length()) return false;
        boolean[] possible = new boolean[secondLength + 1];
        possible[0] = true;
        for (int j = 1; j <= secondLength; j++) {
            possible[j] = possible[j - 1] && s2.charAt(j - 1) == s3.charAt(j - 1);
        }
        for (int i = 1; i <= firstLength; i++) {
            possible[0] = possible[0] && s1.charAt(i - 1) == s3.charAt(i - 1);
            for (int j = 1; j <= secondLength; j++) {
                char target = s3.charAt(i + j - 1);
                possible[j] = (possible[j] && s1.charAt(i - 1) == target)
                        || (possible[j - 1] && s2.charAt(j - 1) == target);
            }
        }
        return possible[secondLength];
    }
}
